CREATE OR REPLACE FUNCTION trip_private.set_leaderboard_public(p_trip uuid, p_public boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF auth.uid() IS NULL OR NOT trip_private.is_captain(p_trip,auth.uid()) THEN RAISE EXCEPTION 'Captain only'; END IF; UPDATE public.trips SET leaderboard_public=coalesce(p_public,false) WHERE id=p_trip; END $$;
CREATE OR REPLACE FUNCTION trip_private.set_public_leaderboard(p_public boolean) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE allowed boolean; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; allowed := coalesce(p_public,false) AND coalesce(trip_private.age_of(auth.uid()),0) >= 18; UPDATE public.player_profiles SET public_leaderboard=allowed WHERE user_id=auth.uid(); RETURN allowed; END $$;
REVOKE ALL ON FUNCTION trip_private.set_leaderboard_public(uuid,boolean), trip_private.set_public_leaderboard(boolean) FROM PUBLIC,anon;
GRANT USAGE ON SCHEMA trip_private TO authenticated;
GRANT EXECUTE ON FUNCTION trip_private.set_leaderboard_public(uuid,boolean), trip_private.set_public_leaderboard(boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.set_leaderboard_public(p_trip uuid,p_public boolean) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT trip_private.set_leaderboard_public(p_trip,p_public) $$;
CREATE OR REPLACE FUNCTION public.set_public_leaderboard(p_public boolean) RETURNS boolean LANGUAGE sql SECURITY INVOKER SET search_path=public AS $$ SELECT trip_private.set_public_leaderboard(p_public) $$;